    "Starting inventory": "Inventario iniziale",
    "Your first interaction": "La tua prima interazione",
    "Every map starts with the starting room. Create it with the button on the left.": "Ogni mappa comincia dalla stanza iniziale. Creala con il pulsante a sinistra.",
    "Pick a tile in the palette and put it on the board; press R to rotate it. For now, place two different tiles: they will be taken out of the box and set up during the game.": "Scegli una tessera nella tavolozza e mettila sul tabellone; premi R per ruotarla. Per ora, piazza due tessere diverse: verranno prese dalla scatola e montate durante la partita.",
    "The Hero button (H) sets the starting squares of our adventurers. Select 2 to 4 squares in the starting room.": "Il pulsante Eroe (H) stabilisce le caselle iniziali dei nostri avventurieri. Seleziona da 2 a 4 caselle nella stanza iniziale.",
    "To reveal the map little by little, we need to create a new room. It appears when an object is used, by programming a trigger that opens a room. Let us try it: click the Object button (O) and pick a door. Then add an “Open a room” trigger.": "Per rivelare la mappa poco a poco, dobbiamo creare una nuova stanza. Appare quando si usa un elemento, programmando un attivatore che apre una stanza. Proviamo: clicca sul pulsante Elemento (O) e scegli una porta. Poi aggiungi un attivatore “Apri una stanza”.",
    "You have created your first interaction with the scenery. In the game, the hero will open the door and release the tiles of the next room. Now, let us fill that room: put a chest in a room and program a trigger that gives items to the players (the other buttons and triggers wait for this).": "Hai creato la tua prima interazione con lo scenario. Nel gioco, l'eroe aprirà la porta e libererà le tessere della stanza successiva. Ora riempiamo quella stanza: metti un forziere in una stanza e programma un attivatore che dia oggetti ai giocatori (gli altri pulsanti e attivatori aspettano questo).",
    "📂 Import a save of the game (.sav)": "📂 Importa un salvataggio del gioco (.sav)",
    "Clear all": "Svuota tutto",
    "Search an item…": "Cerca un oggetto…",
    "Only what the party has": "Solo ciò che ha il gruppo",
    "skills": "abilità",
