    "Imported from the save": "Importato dal salvataggio",
    "This file is not a save of the game.": "Questo file non è un salvataggio del gioco.",
    "For a party of veterans: what it already holds when the campaign starts, won in earlier battles. The party receives it when the campaign begins. Items come from the Workshop (Items and Weapons tabs), the skills from the Skills tab (or the game’s). The item pools of the generated maps leave out the unique items the party already has, and the game never gives an item twice.": "Per un gruppo di veterani: ciò che ha già quando la campagna comincia, conquistato in battaglie precedenti. Il gruppo lo riceve all'inizio della campagna. Gli oggetti vengono dall'Officina (sezioni Oggetti e Armi), le abilità dalla sezione Abilità (o quelle del gioco). Le riserve di oggetti delle mappe generate escludono gli oggetti unici che il gruppo ha già, e il gioco non dà mai un oggetto due volte.",
    "Starting gold": "Oro iniziale",
