    "OGG, MP3 or WAV. Each file plays at its moment in the app: when the monster appears, when it activates, when a hero hits it and when it falls. A moment without a file stays silent. The files are exported next to the map.": "OGG, MP3 o WAV. Ogni file viene riprodotto al suo momento nell'app: quando il mostro appare, quando si attiva, quando un eroe lo colpisce e quando cade. Un momento senza file resta in silenzio. I file vengono esportati accanto alla mappa.",
