    "Now let’s add a chest and make it hand out some items to the party. The other buttons and triggers can wait their turn.": "Ora aggiungiamo un forziere e facciamogli consegnare qualche oggetto al gruppo. Gli altri pulsanti e attivatori possono aspettare il loro turno.",
    "Now choose what the chest gives: in its trigger, pick the item (or another option under “What”).": "Ora scegli cosa dà il forziere: nel suo attivatore, scegli l'oggetto (o un'altra opzione in “Cosa”).",
