    "Broken links": "Collegamenti interrotti",
    "Elements with no link": "Elementi senza collegamento",
    "I know my way around": "So già come muovermi",
    "Are you sure about that?": "Ne sei sicuro?",
    "The tutorial walks you through the editor step by step. If you ever want to revisit it, you can repeat it from ⚙ Settings.": "Il tutorial ti mostra l'editor passo dopo passo. Se un giorno vuoi rivederlo, puoi ripeterlo da ⚙ Impostazioni.",
    "Yes, skip it": "Sì, saltalo",
    "Skip the tutorial? Everything unlocks now. If you change your mind, ⚙ Settings can run it again.": "Saltare il tutorial? Ora si sblocca tutto. Se cambi idea, ⚙ Impostazioni può ripeterlo.",
    "Right here!": "Proprio qui!",
    "With Hero (H), click the squares where the heroes start: choose 2 to 4 squares in the starting room.": "Con Eroe (H), clicca sulle caselle dove partono gli eroi: scegli da 2 a 4 caselle nella stanza iniziale.",
    "Nice work!": "Ottimo lavoro!",
    "The first room is already tied to its door: when a hero opens it, the next room appears on the table. Now let’s add a chest and make it hand out some items to the party. The other buttons and triggers can wait their turn.": "La prima stanza è già legata alla sua porta: quando un eroe la apre, la stanza successiva appare sul tavolo. Ora aggiungiamo un forziere e facciamogli consegnare qualche oggetto al gruppo. Gli altri pulsanti e attivatori possono aspettare il loro turno.",
    "Place a Chest (Object) in a room, select it and add the “Give or take away an item” trigger. Choose what it gives the party when it is opened.": "Piazza un Forziere (Elemento) in una stanza, selezionalo e aggiungi l'attivatore “Dai o togli un oggetto”. Scegli cosa dà al gruppo quando viene aperto.",
    "A brand-new room": "Una stanza nuova di zecca",
    "The door came with its script and has already created a new room tied to it. Lay out its tiles whenever you like. Now for some monsters: the Enemy button is unlocked.": "La porta è arrivata con il suo script e ha già creato una nuova stanza legata a essa. Disponine le tessere quando vuoi. Ora un po' di mostri: il pulsante Nemico è sbloccato.",
    "Let’s put some monsters in a room: press Enemy (E).": "Mettiamo qualche mostro in una stanza: premi Nemico (E).",
    "Ops!": "Ops!",
    "In the Workshop, press “Import…” and bring in about 10 monsters from the game for this map.": "Nell'Officina, premi “Importa…” e porta una decina di mostri dal gioco per questa mappa.",
    "Have a look around the other workshops if you like, then head back to Rooms (◂ Rooms).": "Se vuoi, dai un'occhiata alle altre sezioni dell'Officina, poi torna a Stanze (◂ Stanze).",
    "Now for the room generator. Press ✦ Generate room and click the door that will connect to the new room.": "Ora il generatore di stanze. Premi ✦ Genera stanza e clicca sulla porta che si collegherà alla nuova stanza.",
    "First move the room (drag it or use the arrows) or turn it (R). “Use this” becomes available as soon as the room has moved.": "Prima sposta la stanza (trascinala o usa le frecce) o girala (R). “Usa questa” diventa disponibile appena la stanza si è mossa.",
    "You have built rooms by hand, programmed objects, brought in monsters, and generated a room. Now only the campaign remains: it connects maps on the world map, with scenes, choices, and rewards between them. Press “Start a campaign” and the rest of the editor opens up.": "Hai costruito stanze a mano, programmato elementi, portato mostri e generato una stanza. Ora manca solo la campagna: collega le mappe sulla mappa del mondo, con scene, scelte e ricompense tra di esse. Premi “Inizia una campagna” e il resto dell'editor si apre.",
    "Press “Start a campaign”: everything is unlocked from there.": "Premi “Inizia una campagna”: da lì si sblocca tutto.",
    "Explore the story flow, a scene (and its boxes), the starting inventory, and the story variables. Then go back to Rooms (◂ Rooms) to finish.": "Esplora il flusso della storia, una scena (e i suoi riquadri), l'inventario iniziale e le variabili della storia. Poi torna a Stanze (◂ Stanze) per finire.",
    "Open the Workshop": "Apri l'Officina",
    "Other finer conditions of this feat in the game (first attack of the round, other heroes…) are kept as they are.": "Altre condizioni più sottili di questo traguardo nel gioco (primo attacco del round, altri eroi…) restano come sono.",
    "Otherwise the scene is skipped (the story goes on).": "Altrimenti la scena viene saltata (la storia prosegue).",
    "Pick a box on the left, or add one.": "Scegli un riquadro a sinistra, o aggiungine uno.",
    "Pick a feat on the left, import one from the game, or write a new one.": "Scegli un traguardo a sinistra, importane uno dal gioco o scrivine uno nuovo.",
    "Pick a kind on the left.": "Scegli un tipo a sinistra.",
    "Pick a recipe on the left, import one from the game, or write a new one.": "Scegli uno schema a sinistra, importane uno dal gioco o scrivine uno nuovo.",
    "Pick another object": "Scegli un altro elemento",
    "Pillars go in the sockets of an elevated tile of this room at level {n} (the dots on its edges).": "I pilastri vanno negli incastri di una tessera elevata di questa stanza al livello {n} (i puntini sui suoi bordi).",
    "Pillars hold up elevated tiles: pick the level of that tile ({n} to {n}) on the ribbon first.": "I pilastri sostengono le tessere elevate: prima scegli sulla barra il livello di quella tessera (da {n} a {n}).",
    "Place the city…": "Posiziona la città…",
    "Potions and one-use cards the heroes spend during a quest.": "Pozioni e carte monouso che gli eroi spendono durante un'impresa.",
    "Power of the hero": "Potere dell'eroe",
    "Power of the hero (spend to use)": "Potere dell'eroe (spendilo per usarlo)",
    "Puts something on the board, or takes it off, during play: tiles, objects, monsters, rooms.": "Mette qualcosa sul tabellone, o lo toglie, durante la partita: tessere, elementi, mostri, stanze.",
