    "Smaller than the figure (×0.75)": "Più piccolo della miniatura (×0,75)",
    "Something appears on the board: a tile, an object or monsters.": "Qualcosa appare sul tabellone: una tessera, un elemento o dei mostri.",
    "Takes something off the board: a tile, a room, an object or monsters.": "Toglie qualcosa dal tabellone: una tessera, una stanza, un elemento o dei mostri.",
    "Tall (like a big monster)": "Alto (come un mostro grande)",
    "Tall (like a wall block)": "Alto (come un blocco di muro)",
    "Taller (×1.25)": "Più alto (×1,25)",
    "Text shown after this answer (optional)": "Testo mostrato dopo questa risposta (facoltativo)",
    "The app applies this ability by itself. Changing the text does not change what it does": "L'app applica questa capacità da sola. Cambiare il testo non cambia ciò che fa",
    "The app does not fill this in for this activation": "L'app non compila questo campo per questa attivazione",
    "The behaviour monster’s rule:": "La regola del mostro di comportamento:",
    "The city marker can also be dragged on the map.": "L'indicatore della città si può anche trascinare sulla mappa.",
    "The game's clouds and birds over it": "Le nuvole e gli uccelli del gioco sopra",
    "The game's mist over it": "La nebbia del gioco sopra",
    "The monster lunges forward, roaring…": "Il mostro si lancia in avanti, ruggendo…",
    "The platform is a box standing on the floor: it needs no pillars.": "La piattaforma è una scatola appoggiata sul pavimento: non ha bisogno di pilastri.",
    "The rune: damage, damage types and power": "La runa: danni, tipi di danno e potere",
    "First effect: an ability that may trigger on hits": "Primo effetto: una capacità che può attivarsi quando colpisce",
    "Second effect: another ability that may trigger on hits": "Secondo effetto: un'altra capacità che può attivarsi quando colpisce",
    "The spaces work together, by the game's rule for random spawns: one budget of points for all of them (intensity ÷ {n} × heroes × {n} × progression, Map setup › Balancing) decides how many monsters enter and how strong. All may enter, or just one strong monster.": "Le caselle funzionano insieme, secondo la regola del gioco per le generazioni casuali: un unico budget di punti per tutte (intensità ÷ {n} × eroi × {n} × progressione, Impostazioni mappa › Bilanciamento) decide quanti mostri entrano e quanto sono forti. Possono entrare tutti, o solo un mostro forte.",
    "The workshop has no items yet.": "L'Officina non ha ancora oggetti.",
    "The workshop has no items yet: create or import them in the Items tab.": "L'Officina non ha ancora oggetti: creali o importali nella sezione Oggetti.",
    "The workshop has no items: import or create them in the Items tab.": "L'Officina non ha oggetti: importali o creali nella sezione Oggetti.",
    "The workshop has no monsters: create or import them first (Workshop, top bar).": "L'Officina non ha mostri: prima creali o importali (Officina, barra superiore).",
