    "When the count first changes (announced then)": "Quando il conteggio cambia per la prima volta (annunciato allora)",
    "Which monsters count": "Quali mostri contano",
    "Which one?": "Quale?",
    "Workshop objects (made in the Workshop)": "Elementi dell'Officina (creati nell'Officina)",
    "Workshop tiles (made in the Workshop)": "Tessere dell'Officina (create nell'Officina)",
    "Worn by a hero: a card with its rule, kept in the party’s inventory.": "Indossato da un eroe: una carta con la sua regola, tenuta nell'inventario del gruppo.",
    "Writes the .bmap (download), then clears.": "Scrive il .bmap (download), poi svuota.",
    "✎ Draw a road": "✎ Traccia una strada",
    "✓ Finish this road": "✓ Termina questa strada",
    "Tiles can stand at levels 1, 2 and 3 (the level buttons) on": "Le tessere possono stare ai livelli 1, 2 e 3 (i pulsanti di livello) sui",
    "; the app counts the pillars your boxes have.": "; l'app conta i pilastri che hanno le tue scatole.",
    "pillars (P)": "pilastri (P)",
    "Counts": "Conteggi",
    "keep a number during the map (keys found, seals broken): triggers add to them, and a map objective can wait for the total.": "tengono un numero durante la mappa (chiavi trovate, sigilli spezzati): gli attivatori lo aumentano, e un obiettivo di mappa può aspettare il totale.",
    "Export map": "Esporta mappa",
    "The": "La schermata",
    "Workshop (⚒)": "Officina (⚒)",
    "Map setup": "Impostazioni mappa",
    "Start a campaign": "Inizia una campagna",
    "Press": "Premi",
    "3D": "3D",
    "Hero (H)": "Eroe (H)",
    "Enemy (E)": "Nemico (E)",
    "When the room starts, the game fills these spaces with its own rule for random spawns: points = intensity ÷ {n} × heroes × {n} × progression": "Quando la stanza comincia, il gioco riempie queste caselle con la sua regola per le generazioni casuali: punti = intensità ÷ {n} × eroi × {n} × progressione",
    "When the room opens, the game fills these spaces with its own rule for random spawns: points = intensity ÷ {n} × heroes × {n} × progression": "Quando la stanza si apre, il gioco riempie queste caselle con la sua regola per le generazioni casuali: punti = intensità ÷ {n} × eroi × {n} × progressione",
    "When the room opens, the game fills these spaces with its own rule for random spawns: points = intensity ÷ {n} × heroes × {n} × progression; it takes the highest tier of the map’s range the points pay for (costs {n}, {n}, {n}, {n}, {n}, {n}…), and monsters of the pool that have that tier enter, one per space (up to {n}), while the points last. Leftover points go to the next balanced room. All may enter, or just one strong monster.": "Quando la stanza si apre, il gioco riempie queste caselle con la sua regola per le generazioni casuali: punti = intensità ÷ {n} × eroi × {n} × progressione; prende il grado più alto della fascia della mappa che i punti possono pagare (costi {n}, {n}, {n}, {n}, {n}, {n}…), ed entrano i mostri della riserva che hanno quel grado, uno per casella (fino a {n}), finché durano i punti. I punti avanzati passano alla stanza bilanciata successiva. Possono entrare tutti, o solo un mostro forte.",
    "{n} balanced spaces in this room": "{n} caselle bilanciate in questa stanza",
    "{n} monsters, tier {n}": "{n} mostri, grado {n}",
    "{n} monster, tier {n}": "{n} mostro, grado {n}",
    "{n} monsters, tier {n} (no more miniatures)": "{n} mostri, grado {n} (niente più miniature)",
    "none: no free miniature": "nessuno: nessuna miniatura libera",
    "Room {n} · space {n},{n}": "Stanza {n} · casella {n},{n}",
    "{n} rooms · side quest": "{n} stanze · impresa secondaria",
    "A change applies while this campaign is played, to every copy of the part, also the ones bought or found later.": "Una modifica vale mentre si gioca questa campagna, per ogni copia della parte, anche quelle comprate o trovate in seguito.",
    "Pick a kind of weapon, then its heads, hafts or grips. What you change applies while this campaign is played (to every copy of the part, also the ones bought or found later); what you leave stays as in the game.": "Scegli un tipo di arma, poi le sue teste, aste o impugnature. Ciò che cambi vale mentre si gioca questa campagna (per ogni copia della parte, anche quelle comprate o trovate in seguito); ciò che lasci resta come nel gioco.",
    "Pick a kind of weapon, then its heads, hafts or grips. What you change applies while this campaign is played (to every copy of the part, also the ones bought or found later)": "Scegli un tipo di arma, poi le sue teste, aste o impugnature. Ciò che cambi vale mentre si gioca questa campagna (per ogni copia della parte, anche quelle comprate o trovate in seguito)",
    "Here you prepare the monsters of this campaign. Only the monsters listed here can be placed on the board or drawn from the spawn pool.": "Qui prepari i mostri di questa campagna. Solo i mostri elencati qui possono essere piazzati sul tabellone o estratti dalla riserva di generazione.",
    "A short list is easier to balance and to test; add more as the campaign grows.": "Un elenco breve è più facile da bilanciare e da provare; aggiungine altri man mano che la campagna cresce.",
    "add more as the campaign grows.": "aggiungine altri man mano che la campagna cresce.",
    "Here you choose the items of this campaign: import them from the game, change them (name, rarity, value, damage, abilities) or create your own. Only the items listed here can be dropped by monsters, found or given by triggers, and the": "Qui scegli gli oggetti di questa campagna: importali dal gioco, modificali (nome, rarità, valore, danni, capacità) o crea i tuoi. Solo gli oggetti elencati qui possono essere lasciati dai mostri, trovati o dati dagli attivatori, e la",
    "Strong items early make the fights easy; too few, or weak ones, leave the heroes behind the monsters. Pick them on purpose, thinking of the heroes' progress along the campaign.": "Oggetti forti all'inizio rendono facili i combattimenti; troppo pochi, o deboli, lasciano gli eroi indietro rispetto ai mostri. Sceglili con intenzione, pensando ai progressi degli eroi lungo la campagna.",
    "too few, or weak ones, leave the heroes behind the monsters. Pick them on purpose, thinking of the heroes' progress along the campaign.": "troppo pochi, o deboli, lasciano gli eroi indietro rispetto ai mostri. Sceglili con intenzione, pensando ai progressi degli eroi lungo la campagna.",
    "Each sheet changes one of the six heroes of the game while this campaign is played: name, portrait and animated figure. Their weapons are in the Weapons tab. What you leave as it is stays as in the game.": "Ogni scheda cambia uno dei sei eroi del gioco mentre si gioca questa campagna: nome, ritratto e miniatura animata. Le loro armi sono nella sezione Armi. Ciò che lasci com'è resta come nel gioco.",
    "The item workshop": "L'Officina degli oggetti",
    "The monster workshop": "L'Officina dei mostri",
    "is what random-item triggers draw from.": "è ciò da cui estraggono gli attivatori di oggetti casuali.",
    "The selection of available items is essential for the balance of the game.": "La selezione degli oggetti disponibili è essenziale per l'equilibrio del gioco.",
    "The party has it from the start of the campaign (the heroes pick it in the hero choice)": "Il gruppo lo ha dall'inizio della campagna (gli eroi lo scelgono nella scelta degli eroi)",
