    "the intensity of the rooms with monsters and of the triggers that call monsters from the pool, all by the same step (from −6 to +6, always within 1 to 10);": "l'intensità delle stanze con mostri e degli attivatori che chiamano mostri dalla riserva, tutte con lo stesso passo (da −6 a +6, sempre tra 1 e 10);",
    "the tiers for 1–2, 3 and 4 heroes of the monsters placed by hand, by the game's rule (as ⚖ Balance on a monster).": "i gradi per 1–2, 3 e 4 eroi dei mostri piazzati a mano, secondo la regola del gioco (come ⚖ Bilancia su un mostro).",
    "the campaign progression, the monster and item pools, the monsters themselves, the objects, the triggers and the texts.": "la progressione della campagna, le riserve di mostri e di oggetti, i mostri stessi, gli elementi, gli attivatori e i testi.",
