    "to chain maps on the world map, with scenes, choices and rewards between them.": "per concatenare mappe sulla mappa del mondo, con scene, scelte e ricompense tra di esse.",
    "turn and tilt it with the panel on the board (or Q/E, W/S, right-drag). Esc or the {n}D button returns to the plan.": "girala e inclinala con il pannello sul tabellone (o Q/E, W/S, trascinamento col tasto destro). Esc o il pulsante {n}D torna alla pianta.",
    "{n}D view": "Vista {n}D",
    "{n}D view: drag moves the map": "Vista {n}D: trascina per spostare la mappa",
    "{n}D view: drag moves the map; turn and tilt it with the panel on the board (or Q/E, W/S, right-drag). Esc or the {n}D button returns to the plan.": "Vista {n}D: trascina per spostare la mappa; girala e inclinala con il pannello sul tabellone (o Q/E, W/S, trascinamento col tasto destro). Esc o il pulsante {n}D torna alla pianta.",
    "Campaign started: this map is map {n}. The campaign screen links maps, waypoints and dialogues and places them on the world map.": "Campagna iniziata: questa mappa è la mappa {n}. La schermata della campagna collega mappe, tappe e dialoghi e li posiziona sulla mappa del mondo.",
    "From level {n} up a staircase must stand on tiles: put it on tiles of level {n} (only on the floor, level {n}, may it go off the tiles).": "Dal livello {n} in su una scalinata deve stare su tessere: mettila su tessere del livello {n} (solo sul pavimento, livello {n}, può uscire dalle tessere).",
    "Quick save done (kept in this browser).": "Salvataggio rapido completato (conservato in questo browser).",
    "The item pool has no items: add items to it (Workshop → Items, or Map setup).": "La riserva di oggetti non ha oggetti: aggiungine (Officina → Oggetti, o Impostazioni mappa).",
    "Waypoint added. Place it on the World map tab.": "Tappa aggiunta. Posizionala nella sezione Mappa del mondo.",
    "they stay hidden until the object is used.": "restano nascoste finché l'elemento non viene usato.",
    "“{q}” opens room {n}. Lay its tiles": "“{Q}” apre la stanza {n}. Disponine le tessere",
    "“{q}” opens room {n}. Lay its tiles; they stay hidden until the object is used.": "“{Q}” apre la stanza {n}. Disponine le tessere; restano nascoste finché l'elemento non viene usato.",
    "Answer {n} → end": "Risposta {n} → fine",
    "Answers": "Risposte",
    ". The AppData folder is hidden: paste that path into the address bar of the folder picker.": ". La cartella AppData è nascosta: incolla quel percorso nella barra degli indirizzi della finestra di scelta della cartella.",
    "Author": "Autore",
    "Author (goes into every map and campaign file you export)": "Autore (va in ogni file di mappa e di campagna che esporti)",
    "Brings back the hints of Rooms, the explanations shown the first time a tab opens and the warnings you chose not to see again. Reset all settings: tips and warnings, window positions and sizes, author, export folder and autosave. Your maps and campaigns stay.": "Riporta i suggerimenti di Rooms, le spiegazioni mostrate la prima volta che si apre una sezione e gli avvisi che hai scelto di non vedere più. Ripristina tutte le impostazioni: suggerimenti e avvisi, posizioni e dimensioni delle finestre, autore, cartella di esportazione e salvataggio automatico. Le tue mappe e campagne restano.",
    "Choose folder…": "Scegli cartella…",
    "Close": "Chiudi",
    "Copies the Bigorna\\Mapas path": "Copia il percorso di Bigorna\\Mapas",
    "Copies the Bigorna\\Mapas path; paste it in Explorer's address bar": "Copia il percorso di Bigorna\\Mapas; incollalo nella barra degli indirizzi di Esplora risorse",
    "Copy Bigorna\\Mapas path": "Copia percorso Bigorna\\Mapas",
    "Export folder": "Cartella di esportazione",
    "No folder chosen: exported files are downloaded, and the game (with the mod) brings them from Downloads into its maps list by itself. Choosing the folder is only needed for autosave and the list of files.": "Nessuna cartella scelta: i file esportati vengono scaricati, e il gioco (con il mod) li porta da solo dalla cartella Download al suo elenco di mappe. Scegliere la cartella serve solo per il salvataggio automatico e l'elenco dei file.",
    "Open a .bmap or .bcamp made with Bigorna Rooms (replaces the current work). Brings chosen rooms of another Bigorna map into this one, without replacing it. Quick save keeps a copy in this browser": "Apri un .bmap o .bcamp fatto con Bigorna Rooms (sostituisce il lavoro attuale). Porta stanze scelte di un'altra mappa di Bigorna in questa, senza sostituirla. Il salvataggio rapido conserva una copia in questo browser",
    "Open a .bmap or .bcamp made with Bigorna Rooms (replaces the current work). Brings chosen rooms of another Bigorna map into this one, without replacing it. Quick save keeps a copy in this browser; quick load brings it back.": "Apri un .bmap o .bcamp fatto con Bigorna Rooms (sostituisce il lavoro attuale). Porta stanze scelte di un'altra mappa di Bigorna in questa, senza sostituirla. Il salvataggio rapido conserva una copia in questo browser; il caricamento rapido la riporta.",
    "Settings": "Impostazioni",
    "The maps folder of Descent is": "La cartella delle mappe di Descent è",
    "Tips and settings": "Suggerimenti e impostazioni",
    "Other settings": "Altre impostazioni",
    "Files in the folder…": "File nella cartella…",
