    "). Which monster of the pool enters is drawn in the game.": "). Quale mostro della riserva entra viene estratto nel gioco.",
    "+ Another space": "+ Un'altra casella",
    "Intensity of this room": "Intensità di questa stanza",
    "Tier range {n}–{n}, campaign progression {n} (": "Fascia di gradi {n}–{n}, progressione della campagna {n} (",
    "What the game would do": "Cosa farebbe il gioco",
    "When the group is defeated": "Quando il gruppo viene sconfitto",
    "When the room starts, the game fills these spaces with its own rule for random spawns: points = intensity ÷ {n} × heroes × {n} × progression; it takes the highest tier of the map’s range the points pay for (costs {n}, {n}, {n}, {n}, {n}, {n}…), and monsters of the pool that have that tier enter, one per space (up to {n}), while the points last. Leftover points go to the next balanced room. All may enter, or just one strong monster.": "Quando la stanza comincia, il gioco riempie queste caselle con la sua regola per le generazioni casuali: punti = intensità ÷ {n} × eroi × {n} × progressione; prende il grado più alto della fascia della mappa che i punti possono pagare (costi {n}, {n}, {n}, {n}, {n}, {n}…), ed entrano i mostri della riserva che hanno quel grado, uno per casella (fino a {n}), finché durano i punti. I punti avanzati passano alla stanza bilanciata successiva. Possono entrare tutti, o solo un mostro forte.",
    "change": "cambia",
    "it takes the highest tier of the map’s range the points pay for (costs {n}, {n}, {n}, {n}, {n}, {n}…), and monsters of the pool that have that tier enter, one per space (up to {n}), while the points last. Leftover points go to the next balanced room. All may enter, or just one strong monster.": "prende il grado più alto della fascia della mappa che i punti possono pagare (costi {n}, {n}, {n}, {n}, {n}, {n}…), ed entrano i mostri della riserva che hanno quel grado, uno per casella (fino a {n}), finché durano i punti. I punti avanzati passano alla stanza bilanciata successiva. Possono entrare tutti, o solo un mostro forte.",
    "{n} (= spaces, default)": "{n} (= caselle, predefinito)",
    "{n} balanced space in this room": "{n} casella bilanciata in questa stanza",
    "{n} hero": "{n} eroe",
    "{n} monster, tier {n} (too few points: the minimum)": "{n} mostro, grado {n} (troppo pochi punti: il minimo)",
    "Opened by:": "Aperta da:",
    "Remove this room": "Rimuovi questa stanza",
    "Text when revealed": "Testo quando viene rivelata",
    "Text after the room is set up": "Testo dopo la preparazione della stanza",
    "Text after the board is set up": "Testo dopo la preparazione del tabellone",
    "What the heroes find in it: a person, an object (the interaction tokens)": "Cosa trovano gli eroi al suo interno: una persona, un oggetto (i segnalini interazione)",
    "Tile {n} is in another room: reusing it here needs that room removed first": "La tessera {n} è in un'altra stanza: per riusarla qui bisogna prima rimuovere quella stanza",
    "give one an “{q}” trigger": "dai a uno di essi un attivatore “{Q}”",
    "no object opens this room; give one an “{q}” trigger": "nessun elemento apre questa stanza; dai a uno di essi un attivatore “{Q}”",
