    "Opens": "Apre",
    "a new room can be created here too.": "qui si può anche creare una nuova stanza.",
    "opened by “{q}”": "aperta da “{Q}”",
    "A scene (dialogue boxes)": "Una scena (riquadri di dialogo)",
    "A scene of dialogue boxes (like the story flow), your own film full screen, a sound effect of the game or your own sound file. (a scene, a video, a sound)": "Una scena di riquadri di dialogo (come il flusso della storia), il tuo filmato a schermo intero, un effetto sonoro del gioco o il tuo file audio. (una scena, un video, un suono)",
    "A sound (game effect or your own file)": "Un suono (effetto del gioco o il tuo file)",
