    "A video (your own film)": "Un video (il tuo filmato)",
    "Add / Remove…": "Aggiungi / Rimuovi…",
    "Add a trigger to “{q}”": "Aggiungi un attivatore a “{Q}”",
    "Add or remove?": "Aggiungere o rimuovere?",
    "Add what?": "Aggiungere cosa?",
    "Adds to (or removes from) the item pool or the monster spawn pool of the map, for the rest of the map. (item, monster spawn)": "Aggiunge alla (o toglie dalla) riserva di oggetti o riserva di generazione dei mostri della mappa, per il resto della mappa. (oggetto, generazione di mostri)",
    "Add…": "Aggiungi…",
