    "Monster spawn": "Generazione di mostri",
    "Play a scene, video or sound": "Riproduci una scena, un video o un suono",
    "Play what?": "Riprodurre cosa?",
    "Puts something on the board, or takes it off, during play: tiles, objects, monsters, rooms. (a tile, an object, spawn monsters, a tile, a room, an object, a monster)": "Mette qualcosa sul tabellone, o lo toglie, durante la partita: tessere, elementi, mostri, stanze. (una tessera, un elemento, genera mostri, una tessera, una stanza, un elemento, un mostro)",
    "Remove…": "Rimuovi…",
    "Something appears on the board: a tile, an object or monsters. (a tile, an object, spawn monsters)": "Qualcosa appare sul tabellone: una tessera, un elemento o dei mostri. (una tessera, un elemento, genera mostri)",
    "Takes something off the board: a tile, a room, an object or monsters. (a tile, a room, an object, a monster)": "Toglie qualcosa dal tabellone: una tessera, una stanza, un elemento o dei mostri. (una tessera, una stanza, un elemento, un mostro)",
    "What happens when a hero uses this object. Several triggers run in order.": "Cosa succede quando un eroe usa questo elemento. Più attivatori scattano in ordine.",
    "Puts something on the board, or takes it off, during play: tiles, objects, monsters, rooms. (a tile, an object, a tile, a room, an object, a monster)": "Mette qualcosa sul tabellone, o lo toglie, durante la partita: tessere, elementi, mostri, stanze. (una tessera, un elemento, una tessera, una stanza, un elemento, un mostro)",
    "What happens once, when the count reaches {n} (the total of the counter). Several triggers run in order.": "Cosa succede una volta, quando il conteggio arriva a {n} (il totale del contatore). Più attivatori scattano in ordine.",
    "When the balanced group is defeated: “{q}”": "Quando il gruppo bilanciato viene sconfitto: “{Q}”",
    "A goal on this map, announced when the monster is defeated and listed with the objectives. An objective does not end the map: the mission does (Map setup). An objective can be chosen there as the mission.": "Una meta di questa mappa, annunciata quando il mostro viene sconfitto ed elencata con gli obiettivi. Un obiettivo non termina la mappa: lo fa la missione (Impostazioni mappa). Lì si può scegliere un obiettivo come missione.",
    "From when the monster is defeated, the round counter runs the triggers inside: every N rounds (as many times as you say, or to the end of the map), or once, N rounds later. For a wave, put “{q}” inside: the spawn has its own “{q}”.": "Da quando il mostro viene sconfitto, il contatore dei round fa scattare gli attivatori interni: ogni N round (quante volte dici tu, o fino alla fine della mappa), oppure una volta, N round dopo. Per un'ondata, metti dentro “{Q}”: la generazione ha il suo “{Q}”.",
    "When this monster is defeated: “{q}”": "Quando questo mostro viene sconfitto: “{Q}”",
    "If the test fails: “{q}”": "Se la prova fallisce: “{Q}”",
