    "Takes one tile off the board with everything on it (objects, pillars, monsters). Frees it for reuse in a later room.": "Toglie una tessera dal tabellone con tutto ciò che c'è sopra (elementi, pilastri, mostri). La libera per riutilizzarla in una stanza successiva.",
