    "[count] is the name of the counter (highlighted like the rule words of the game), [n] the count after this trigger, [total] the total of the counter (Counts button). Missions and requirements can wait for the counter to reach a number (“{q}”).": "[count] è il nome del contatore (evidenziato come le parole delle regole del gioco), [n] il conteggio dopo questo attivatore, [total] il totale del contatore (pulsante Conteggi). Missioni e requisiti possono aspettare che il contatore arrivi a un numero (“{Q}”).",
