    "each answer may show a text afterwards and have its own triggers.": "ogni risposta può mostrare un testo dopo e avere i suoi attivatori.",
    "\"{q}\": objective without its object": "\"{Q}\": obiettivo senza il suo elemento",
    "A counter reaches a number": "Un contatore arriva a un numero",
    "An object is used (click it)": "Si usa un elemento (cliccaci sopra)",
    "An objective does not end the map. To make it the mission, pick it in Map setup → Final mission → “{q}”.": "Un obiettivo non termina la mappa. Per renderlo la missione, sceglilo in Impostazioni mappa → Missione finale → “{Q}”.",
    "Completed when": "Completato quando",
    "Completed when it reaches": "Completato quando arriva a",
    "Declared at the table": "Dichiarato al tavolo",
    "Declared at the table: the app only shows the objective text among the objectives and checks nothing by itself. It counts as completed when the table marks it in the Bigorna panel of the game (F{n} → “{q}”)": "Dichiarato al tavolo: l'app mostra solo il testo dell'obiettivo tra gli obiettivi e non verifica niente da sola. Conta come completato quando il tavolo lo spunta nel pannello Bigorna del gioco (F{n} → “{Q}”)",
    "Declared at the table: the app only shows the objective text among the objectives and checks nothing by itself. It counts as completed when the table marks it in the Bigorna panel of the game (F{n} → “{q}”); only then the requirement “{q}” holds and, if it was chosen as the mission, the map ends.": "Dichiarato al tavolo: l'app mostra solo il testo dell'obiettivo tra gli obiettivi e non verifica niente da sola. Conta come completato quando il tavolo lo spunta nel pannello Bigorna del gioco (F{n} → “{Q}”); solo allora il requisito “{Q}” è valido e, se è stato scelto come missione, la mappa termina.",
    "Give each object that counts (each key, each lever) an “{q}” trigger with this counter. The mission ends by itself when the number is reached.": "Dai a ogni elemento che conta (ogni chiave, ogni leva) un attivatore “{Q}” con questo contatore. La missione termina da sola quando si raggiunge il numero.",
    "Monsters are defeated": "I mostri vengono sconfitti",
