    ", part": ", parte",
    ": part": ": parte",
    ": pick a weapon, open one of its parts and change it, or create a new part for one of the three places. The weapon itself only keeps its name.": ": scegli un'arma, apri una delle sue parti e cambiala, o crea una nuova parte per uno dei tre posti. L'arma in sé conserva solo il nome.",
    "A change applies while this map is played, to every copy of the part, also the ones bought or found later.": "Una modifica vale mentre si gioca questa mappa, per ogni copia della parte, anche quelle comprate o trovate in seguito.",
    "A different monster each time": "Un mostro diverso ogni volta",
    "A feat is a goal a hero pursues during the quests (attack with a spear {n} times, open {n} chests…). The game counts it by itself and gives the reward when it is done. Import the game’s feats (they stay as in the game; duplicate one to change it), or write new ones for any hero.": "Un traguardo è un obiettivo che un eroe persegue durante le imprese (attaccare con una lancia {n} volte, aprire {n} forzieri…). Il gioco lo conta da solo e dà la ricompensa quando è compiuto. Importa i traguardi del gioco (restano come nel gioco; duplicane uno per cambiarlo), o scrivine di nuovi per qualsiasi eroe.",
    "A new head of the workshop for this weapon: an item the party gets from a trigger or crafts with a recipe": "Una nuova testa dell'Officina per quest'arma: un oggetto che il gruppo ottiene da un attivatore o fabbrica con uno schema",
    "A new weapon in its place": "Una nuova arma al suo posto",
    "A recipe says what an item costs in crafting materials when the heroes craft it in the camp. Import the game’s recipes to change their costs, or write one for an item of the workshop. The party learns a recipe from a “{q}” trigger, or knows it from the start.": "Uno schema dice quanto costa un oggetto in materiali di fabbricazione quando gli eroi lo fabbricano all'accampamento. Importa gli schemi del gioco per cambiarne i costi, o scrivine uno per un oggetto dell'Officina. Il gruppo impara uno schema da un attivatore “{Q}”, o lo conosce dall'inizio.",
    "A skill card is unlocked for the hero (the physical card at the table)": "Una carta abilità viene sbloccata per l'eroe (la carta fisica al tavolo)",
    "A skill card is unlocked for the hero (the physical card at the table); a recipe is learned by the party.": "Una carta abilità viene sbloccata per l'eroe (la carta fisica al tavolo); uno schema viene imparato dal gruppo.",
    "A workshop tile is your own physical piece: once per room, reusing it in another room asks to remove the earlier one, and it takes pillars in its sockets (between two squares on a straight edge) when elevated. In the app the mod builds it as a flat tile of this shape, with your picture or colour, and the heroes walk on it like on any tile.": "Una tessera dell'Officina è un tuo pezzo fisico: una volta per stanza, riusarla in un'altra stanza chiede di rimuovere quella precedente, e accetta pilastri nei suoi incastri (tra due quadrati su un bordo dritto) quando è elevata. Nell'app il mod la costruisce come una tessera piatta di questa forma, con la tua immagine o il tuo colore, e gli eroi ci camminano sopra come su qualsiasi tessera.",
