    "The six profiles of the game (class, weapons, skills and feats) go into the campaign. Each is played by the game’s hero (as in the game) or by a hero of your roster, put in it on the hero’s own sheet.": "I sei profili del gioco (classe, armi, abilità e traguardi) entrano nella campagna. Ognuno è giocato dall'eroe del gioco (come nel gioco) o da un eroe della tua rosa, assegnato dalla scheda dell'eroe stesso.",
    "The six profiles of the game (class, weapons, skills and feats) go into the map. Each is played by the game’s hero (as in the game) or by a hero of your roster, put in it on the hero’s own sheet.": "I sei profili del gioco (classe, armi, abilità e traguardi) entrano nella mappa. Ognuno è giocato dall'eroe del gioco (come nel gioco) o da un eroe della tua rosa, assegnato dalla scheda dell'eroe stesso.",
