    "Delete hero": "Elimina eroe",
    "The animated drawing of the game hero of its profile.": "Il disegno animato dell'eroe del gioco del suo profilo.",
    "(the profile’s)": "(quella del profilo)",
    "Each weapon has one hero in the game (its parts, the shop, the inventory and the feats follow it). Picking the weapon of another hero hands him this one in exchange. The numbers come from the weapons: they are changed in the Weapons tab. The weapons belong to the profile: they stay with it if the hero leaves.": "Ogni arma ha un eroe nel gioco (le sue parti, la bottega, l'inventario e i traguardi lo seguono). Scegliere l'arma di un altro eroe gli passa questa in cambio. I numeri vengono dalle armi: si cambiano nella sezione Armi. Le armi appartengono al profilo: restano con esso se l'eroe se ne va.",
    "The weapons belong to the profile: they stay with it if the hero leaves.": "Le armi appartengono al profilo: restano con esso se l'eroe se ne va.",
    "went back to the roster.": "è tornato nella rosa.",
    "Who plays this profile": "Chi gioca questo profilo",
    "the game’s hero": "l'eroe del gioco",
    "now in the profile of": "ora nel profilo di",
    "Pick a hero of the roster to play this profile in the place of the game’s hero.": "Scegli un eroe della rosa per giocare questo profilo al posto dell'eroe del gioco.",
    "now plays the profile of": "ora gioca il profilo di",
    "is back in the profile.": "è tornato nel profilo.",
    "Heads, hafts and grips of the weapons, imported in a package or made here: they are in the Weapons tab, under the weapon they belong to.": "Teste, aste e impugnature delle armi, importate in un pacchetto o create qui: sono nella sezione Armi, sotto l'arma a cui appartengono.",
