    "Charms a hero carries; some have an effect the app applies.": "Amuleti che un eroe porta con sé; alcuni hanno un effetto che l'app applica.",
    "Crafting materials: loot is paid in them and recipes cost them.": "Materiali di fabbricazione: il bottino si paga con essi e gli schemi li richiedono.",
