    "Choose the type first: it decides the figure and the animated art in the app (the game has no others) and the behaviour rules of that family. Then the rest of the sheet opens.": "Prima scegli il tipo: decide la miniatura e l'arte animata nell'app (il gioco non ne ha altre) e le regole di comportamento di quella famiglia. Poi si apre il resto della scheda.",
