    "Drag the pieces to put the weapon together as you want it; the wheel (or the slider) changes the size of the chosen piece, Shift+wheel, Q/E or the turn slider rotate it, the arrows nudge it. A piece only shows inside its own box: what goes out of it is cut (shown faint).": "Trascina i pezzi per assemblare l'arma come la vuoi; la rotella (o il cursore) cambia la dimensione del pezzo scelto, Maiusc+rotella, Q/E o il cursore di rotazione lo girano, le frecce lo spostano di poco. Un pezzo si vede solo dentro il suo riquadro: ciò che ne esce viene tagliato (mostrato sbiadito).",
    "Drag the pieces to put the weapon together, forge the template and bake the pictures": "Trascina i pezzi per assemblare l'arma, forgia il modello e genera le immagini",
    "Duplicate": "Duplica",
    "Each sheet changes one of the six heroes of the game while this map is played: name, portrait and animated figure. Their weapons are in the Weapons tab. What you leave as it is stays as in the game.": "Ogni scheda cambia uno dei sei eroi del gioco mentre si gioca questa mappa: nome, ritratto e miniatura animata. Le loro armi sono nella sezione Armi. Ciò che lasci com'è resta come nel gioco.",
