    "None yet (“{q}” above). A new head is an item: the party gets it from a “{q}” trigger or crafts it with a recipe, and fits it in the armory.": "Ancora nessuna (“{Q}” qui sopra). Una nuova testa è un oggetto: il gruppo la ottiene da un attivatore “{Q}” o la fabbrica con uno schema, e la monta in armeria.",
