    "Pick a kind of weapon, then its heads, hafts or grips. What you change applies while this map is played (to every copy of the part, also the ones bought or found later)": "Scegli un tipo di arma, poi le sue teste, aste o impugnature. Ciò che cambi vale mentre si gioca questa mappa (per ogni copia della parte, anche quelle comprate o trovate in seguito)",
    "Pick a kind of weapon, then its heads, hafts or grips. What you change applies while this map is played (to every copy of the part, also the ones bought or found later); what you leave stays as in the game.": "Scegli un tipo di arma, poi le sue teste, aste o impugnature. Ciò che cambi vale mentre si gioca questa mappa (per ogni copia della parte, anche quelle comprate o trovate in seguito); ciò che lasci resta come nel gioco.",
    "Picture…": "Immagine…",
