    "Potions and one-use cards the heroes spend during a quest. Only items listed in the workshop can be given by triggers, rewards and dialogues, dropped by monsters or crafted.": "Pozioni e carte monouso che gli eroi spendono durante un'impresa. Solo gli oggetti elencati nell'Officina possono essere dati da attivatori, ricompense e dialoghi, lasciati dai mostri o fabbricati.",
