    "Rarity": "Rarità",
    "Recalculate the other tiers from this one with the game's own curve: health grows ×{n}, ×{n}, ×{n}, ×{n}, ×{n}, ×{n}, ×{n} per tier, defense +{n} per tier, attack +{n} up to tier {n} and then +{n} every two tiers. With this tier alone, it creates the tiers up to {n}": "Ricalcola gli altri gradi a partire da questo con la curva del gioco stesso: la salute cresce ×{n}, ×{n}, ×{n}, ×{n}, ×{n}, ×{n}, ×{n} per grado, la difesa +{n} per grado, l'attacco +{n} fino al grado {n} e poi +{n} ogni due gradi. Con solo questo grado, crea i gradi fino a {n}",
