    "Strong items early make the fights easy; too few, or weak ones, leave the heroes behind the monsters. Pick them on purpose, thinking of the heroes' progress along the map.": "Oggetti forti all'inizio rendono facili i combattimenti; troppo pochi, o deboli, lasciano gli eroi indietro rispetto ai mostri. Sceglili con intenzione, pensando ai progressi degli eroi lungo la mappa.",
