    "What the monster does on its turn, in order; “{q}” chains them. Speed, damage, aim, attack, range, healing, shield, initiative and range type are the numbers the app uses; the text is what the players read.": "Cosa fa il mostro nel suo turno, in ordine; “{Q}” le concatena. Velocità, danni, mira, attacco, gittata, cura, scudo, iniziativa e tipo di gittata sono i numeri che usa l'app; il testo è ciò che leggono i giocatori.",
