    "Worn by a hero: a card with its rule, kept in the party’s inventory. Only items listed in the workshop can be given by triggers, rewards and dialogues, dropped by monsters or crafted.": "Indossato da un eroe: una carta con la sua regola, tenuta nell'inventario del gruppo. Solo gli oggetti elencati nell'Officina possono essere dati da attivatori, ricompense e dialoghi, lasciati dai mostri o fabbricati.",
    "Write plain text. The buttons put in the names the app fills in ([monster] = the name of this monster, [hero] = the name of the hero it targets (or another name the app fills in)) and the game icons. Rule words like scar, terrify or focus become the game’s highlighted terms by themselves.": "Scrivi testo semplice. I pulsanti inseriscono i nomi che compila l'app ([monster] = il nome di questo mostro, [hero] = il nome dell'eroe che prende di mira (o un altro nome che compila l'app)) e le icone del gioco. Le parole delle regole come scar, terrify o focus diventano da sole i termini evidenziati del gioco.",
