    "Boxes of text, questions and videos (your own films), played in a row (it goes after the selected card)": "Riquadri di testo, domande e video (i tuoi filmati), riprodotti in sequenza (va dopo la scheda selezionata)",
    "Boxes of “{q}”: drag from a box’s ● (or an answer’s ●) onto another box to say what comes next": "Riquadri di “{Q}”: trascina dal ● di un riquadro (o dal ● di una risposta) a un altro riquadro per dire cosa viene dopo",
    "Boxes play in the order of the arrows, starting at the first. A question box branches: each answer leads to its own next box. A video box plays your own film (MP{n} or WebM) between the other boxes.": "I riquadri vengono riprodotti nell'ordine delle frecce, partendo dal primo. Un riquadro domanda si dirama: ogni risposta porta al suo riquadro successivo. Un riquadro video riproduce il tuo filmato (MP{n} o WebM) tra gli altri riquadri.",
    "Build the rooms of this map": "Costruisci le stanze di questa mappa",
