    "the bell hangs in its frame: a bell on the table takes the bell frame, and with one frame only one bell hangs at a time": "la campana è appesa al suo supporto: una campana sul tavolo occupa il supporto della campana, e con un solo supporto si può appendere una sola campana alla volta",
