    "Every map, side quest and waypoint has a place here and a marker kind: main quest, side quest, narrative event or city visit.": "Ogni mappa, impresa secondaria e tappa ha un posto qui e un tipo di indicatore: impresa principale, impresa secondaria, evento narrativo o visita in città.",
    "Everything of this campaign is erased from the editor, and it cannot be undone:": "Tutto ciò che riguarda questa campagna viene cancellato dall'editor, e non si può annullare:",
    "Export campaign": "Esporta campagna",
    "Export, then delete": "Esporta, poi elimina",
    "Files already exported stay in the folder": "I file già esportati restano nella cartella",
    "Files already exported stay in the folder; delete them there if you want. Autosave stops following this campaign, so it will not erase them. The game keeps the progress of any party that played it.": "I file già esportati restano nella cartella; eliminali lì se vuoi. Il salvataggio automatico smette di seguire questa campagna, quindi non li cancellerà. Il gioco conserva i progressi di qualsiasi gruppo che l'abbia giocata.",
    "Fit the whole flow in the view": "Inquadra tutto il flusso nella vista",
