    "On the world map as": "Sulla mappa del mondo come",
    "PNG or JPG, {n}:{n} ({n}×{n} fits exactly). It covers the whole frame the game shows": "PNG o JPG, {n}:{n} ({n}×{n} si adatta esattamente). Copre tutta la cornice che mostra il gioco",
    "PNG or JPG, {n}:{n} ({n}×{n} fits exactly). It covers the whole frame the game shows; the game's water, burnt land, place names and roads are hidden. The mist covers a fixed region of the game's own map (the Mistlands).": "PNG o JPG, {n}:{n} ({n}×{n} si adatta esattamente). Copre tutta la cornice che mostra il gioco; l'acqua, la terra bruciata, i nomi dei luoghi e le strade del gioco vengono nascosti. La nebbia copre una regione fissa della mappa del gioco stesso (le Terre della Nebbia).",
    "Place this waypoint on the world map": "Posiziona questa tappa sulla mappa del mondo",
    "Plays as": "Si riproduce come",
    "Point at a line to light its arrow. To see where a card leads, click its ●.": "Passa il puntatore su una linea per illuminarne la freccia. Per vedere dove porta una scheda, clicca sul suo ●.",
