    "Simulation": "Simulazione",
    "Stay and fill them": "Resta e compilali",
    "Story flow": "Flusso della storia",
    "The choices the campaign remembers from one map to the next: spared the bandit, sided with the rebels, took the cursed ring… A choice is set when the party picks an answer ticked “{q}” (or by a “{q}” action) and stays for the rest of the campaign. Cards of the story flow and triggers of the maps can then happen only if the party made it, or did not.": "Le scelte che la campagna ricorda da una mappa all'altra: ha risparmiato il bandito, si è schierato con i ribelli, ha preso l'anello maledetto… Una scelta viene impostata quando il gruppo sceglie una risposta spuntata con “{Q}” (o con un'azione “{Q}”) e resta per il resto della campagna. Le schede del flusso della storia e gli attivatori delle mappe possono quindi avvenire solo se il gruppo l'ha fatta, o se non l'ha fatta.",
    "The party moves on the world map (it goes after the selected card)": "Il gruppo si sposta sulla mappa del mondo (va dopo la scheda selezionata)",
    "The scene goes on with the next box when the film ends.": "La scena prosegue con il riquadro successivo quando il filmato finisce.",
    "Then:": "Poi:",
    "They are exported as they are. Fill them, or delete the ones you do not need.": "Vengono esportati così come sono. Compilali, o elimina quelli che non ti servono.",
