    "World map position: {n}, {n}.": "Posizione sulla mappa del mondo: {n}, {n}.",
    "Write the boxes of this scene": "Scrivi i riquadri di questa scena",
    "Write the boxes ▸": "Scrivi i riquadri ▸",
    "Writes the .bcamp and its maps (download), then deletes.": "Scrive il .bcamp e le sue mappe (download), poi elimina.",
    "You are building the rooms of this map. Pick another map, or add maps, waypoints and dialogues, on the campaign screen (“{q}” above).": "Stai costruendo le stanze di questa mappa. Scegli un'altra mappa, o aggiungi mappe, tappe e dialoghi, nella schermata della campagna (“{Q}” qui sopra).",
    "after Map {n}": "dopo Mappa {n}",
    "after Side quest {n}": "dopo Impresa secondaria {n}",
