    "before anything it opens the campaign.": "prima di tutto apre la campagna.",
    "campaign progression {n} (Map setup → Balancing).": "progressione della campagna {n} (Impostazioni mappa → Bilanciamento).",
    "double-click the background adds a box": "doppio clic sullo sfondo aggiunge un riquadro",
    "drag from its ● onto another card to link (the target comes after)": "trascina dal suo ● a un'altra scheda per collegarle (quella di arrivo viene dopo)",
