    "narrator": "narratore",
    "nothing depends on it yet: pick it in “{q}” of a card, or as the requirement “{q}” of a map trigger.": "ancora non dipende niente da essa: sceglila in “{Q}” di una scheda, o come requisito “{Q}” di un attivatore di mappa.",
    "nothing sets it yet: tick “{q}” in a question box and give it this name. Until then “{q}” is never true.": "ancora niente la imposta: spunta “{Q}” in un riquadro domanda e dalle questo nome. Fino ad allora “{Q}” non è mai vera.",
    "only a question may branch": "solo una domanda può diramarsi",
    "progression {n}": "progressione {n}",
    "question": "domanda",
    "the name is yours.": "il nome lo scegli tu.",
    "the scenes that follow it play in the same visit.": "le scene che la seguono si riproducono nella stessa visita.",
    "the story flow: {n} card(s), {n} scene(s) with their boxes, {n} story variable(s)": "il flusso della storia: {n} scheda/e, {n} scena/e con i loro riquadri, {n} variabile/i della storia",
    "the workshop: {n} monster(s), {n} NPC(s), {n} item(s), {n} hero(es), {n} weapon(s), {n} recipe(s), {n} feat(s), {n} tile(s)/object(s) of your own": "l'Officina: {n} mostro/i, {n} PNG, {n} oggetto/i, {n} eroe/i, {n} arma/i, {n} schema/i, {n} traguardo/i, {n} tessera/e / elemento/i tuoi",
    "the world map positions, the rewards, the music and videos chosen": "le posizioni sulla mappa del mondo, le ricompense, la musica e i video scelti",
    "with your own map picture, draw the roads on the left": "con la tua immagine della mappa, traccia le strade a sinistra",
    "without a name": "senza nome",
    "{n} box(es): text, questions and videos (your own films), played one after the other in the same frame. Played at this point of the story: after a map it is the map’s closing scene": "{n} riquadro/i: testo, domande e video (i tuoi filmati), riprodotti uno dopo l'altro nella stessa cornice. Si riproduce in questo punto della storia: dopo una mappa è la scena conclusiva della mappa",
    "{n} box(es): text, questions and videos (your own films), played one after the other in the same frame. Played at this point of the story: after a map it is the map’s closing scene; after a waypoint it plays on arrival; before anything it opens the campaign.": "{n} riquadro/i: testo, domande e video (i tuoi filmati), riprodotti uno dopo l'altro nella stessa cornice. Si riproduce in questo punto della storia: dopo una mappa è la scena conclusiva della mappa; dopo una tappa si riproduce all'arrivo; prima di tutto apre la campagna.",
    "{n} room(s)": "{n} stanza/e",
