    "Original maps": "Mappe originali",
    "The original maps of the game are read by the Bigorna mod from your own copy of the game: start the game once with the mod installed (the title screen prepares them), then open the editor from the Editor folder of the game again.": "Le mappe originali del gioco vengono lette dal mod Bigorna dalla tua copia del gioco: avvia il gioco una volta con il mod installato (la schermata del titolo le prepara), poi riapri l'editor dalla cartella Editor del gioco.",
    "The quests of the game, converted into maps of the editor: tiles, objects, rooms, monsters and the logic the triggers can say.": "Le imprese del gioco, convertite in mappe dell'editor: tessere, elementi, stanze, mostri e la logica che gli attivatori riescono a esprimere.",
    "Each map comes with notes on what was simplified (Map setup).": "Ogni mappa arriva con note su ciò che è stato semplificato (Impostazioni mappa).",
