    "The skills of this hero, by XP": "Le abilità di questo eroe, per PE",
    "This erases everything the editor keeps: the map or campaign on screen, the Workshop (monsters, items, materials, objects, imported or made), the packages (in the app: the Pacotes folder, every package in it), the pictures kept by the editor, the quick save, your archetypes, the hints and warnings, window positions and sizes, the author, the export folder and the autosave.": "Questo cancella tutto ciò che l'editor conserva: la mappa o la campagna sullo schermo, l'Officina (mostri, oggetti, materiali, elementi, importati o creati), i pacchetti (nell'app: la cartella Pacotes, con tutti i pacchetti che contiene), le immagini conservate dall'editor, il salvataggio rapido, i tuoi archetipi, i suggerimenti e gli avvisi, le posizioni e le dimensioni delle finestre, l'autore, la cartella di esportazione e il salvataggio automatico.",
    "Reset everything: the work on screen, the Workshop and the packages, the pictures kept, the quick save, archetypes, tips and warnings, window positions and sizes, author, export folder and autosave. The language stays.": "Ripristina tutto: il lavoro sullo schermo, l'Officina e i pacchetti, le immagini conservate, il salvataggio rapido, gli archetipi, i suggerimenti e gli avvisi, le posizioni e le dimensioni delle finestre, l'autore, la cartella di esportazione e il salvataggio automatico. La lingua resta.",
