    "it stands on the game box of Act I, with its floor at level 3 and its walls 2 above. It takes no pillars.": "sta sulla scatola del gioco dell'Atto I, con il pavimento al livello 3 e le pareti 2 più in alto. Non ha pilastri.",
    "it stands on the floor, with its walls 2 above it. It takes no pillars; it may stand on the game box (all its squares over the box).": "sta sul pavimento, con le pareti 2 più in alto. Non ha pilastri; può stare sulla scatola del gioco (tutti i suoi quadrati sopra la scatola).",
