    "Armor is played at the table: the app keeps it in the inventory and shows its card, with your name, text and art.": "L'armatura si gioca al tavolo: l'app la tiene nell'inventario e ne mostra la carta, con il tuo nome, testo e arte.",
    "A consumable is played at the table: the app keeps it in the inventory and shows its card, with your name, text and art.": "Un consumabile si gioca al tavolo: l'app lo tiene nell'inventario e ne mostra la carta, con il tuo nome, testo e arte.",
