    "Import activations": "Importa attivazioni",
    "Yours (the roll)": "Tue (la raccolta)",
    "The game": "Il gioco",
    "Bold: the name of a rule, a word to stand out": "Grassetto: il nome di una regola, una parola da mettere in risalto",
    "Italics: the narration, read aloud": "Corsivo: la narrazione, letta ad alta voce",
    "The game’s icons": "Le icone del gioco",
