    "(optional, shown before the activation)": "(facoltativo, mostrato prima dell'attivazione)",
    "Bloodlust: after the attack, the target is pushed 2 spaces.": "Sete di sangue: dopo l'attacco, il bersaglio viene spinto di 2 caselle.",
    "What the hero must do (in the feats window it comes after the name, in bold)": "Cosa deve fare l'eroe (nella finestra dei traguardi viene dopo il nome, in grassetto)",
    "Has used both weapons this round": "Ha usato entrambe le armi in questo round",
    "The hero’s health": "La salute dell'eroe",
    "The hero attacked this round": "L'eroe ha attaccato in questo round",
    "Has already attacked this round": "Ha già attaccato in questo round",
