    "Another hero is injured": "Un altro eroe è ferito",
    "No other hero is injured": "Nessun altro eroe è ferito",
    "Any hero’s action counts (not only this hero’s)": "Conta l'azione di qualsiasi eroe (non solo di questo eroe)",
    "Attacks this round": "Attacchi in questo round",
    "Before any hero attacks this round": "Prima che qualsiasi eroe attacchi in questo round",
