    "Interactions this round": "Interazioni in questo round",
    "Before any hero interacts this round": "Prima che qualsiasi eroe interagisca in questo round",
    "After some hero interacted this round": "Dopo che qualche eroe ha interagito in questo round",
    "The other heroes attacked this round": "Gli altri eroi hanno attaccato in questo round",
    "Every other hero attacked this round": "Tutti gli altri eroi hanno attaccato in questo round",
    "Not every other hero attacked this round": "Non tutti gli altri eroi hanno attaccato in questo round",
    "Every hero attacked this round": "Tutti gli eroi hanno attaccato in questo round",
    "Not every hero attacked this round": "Non tutti gli eroi hanno attaccato in questo round",
    "At least this many monsters on the map": "Almeno questo numero di mostri sulla mappa",
    "The monster has a condition": "Il mostro ha una condizione",
    "The monster has at least this many conditions": "Il mostro ha almeno questo numero di condizioni",
    "The monster already damaged": "Il mostro già danneggiato",
    "The monster is already damaged": "Il mostro è già danneggiato",
